"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["31965"],{28978(e,n,s){s.r(n),s.d(n,{metadata:()=>t,default:()=>d,frontMatter:()=>r,contentTitle:()=>o,toc:()=>c,assets:()=>h});var t=JSON.parse('{"id":"nhcx/v1/concepts/what-nhcx-is","title":"What NHCX is","description":"The exchange, what it aims to achieve, what it is made of, who is on it, and what changes for a hospital that joins.","source":"@site/docs/nhcx/v1/concepts/what-nhcx-is.md","sourceDirName":"nhcx/v1/concepts","slug":"/nhcx/v1/concepts/what-nhcx-is","permalink":"/docs/pr-9/docs/nhcx/v1/concepts/what-nhcx-is","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1788936730000,"sidebarPosition":2,"frontMatter":{"title":"What NHCX is","sidebar_label":"What NHCX is","description":"The exchange, what it aims to achieve, what it is made of, who is on it, and what changes for a hospital that joins.","verification":"unverified","source":"NHCX sandbox portal, Introduction and Technical Specifications pages; NHCX Usecases (NHA); NHCX Documentation v1.5.0","sidebar_position":2},"sidebar":"nhcx-v1-overview","previous":{"title":"Core concepts","permalink":"/docs/pr-9/docs/nhcx/v1/concepts/"},"next":{"title":"Claim settlement","permalink":"/docs/pr-9/docs/nhcx/v1/concepts/claim-settlement"}}'),a=s(62540),i=s(43023);let r={title:"What NHCX is",sidebar_label:"What NHCX is",description:"The exchange, what it aims to achieve, what it is made of, who is on it, and what changes for a hospital that joins.",verification:"unverified",source:"NHCX sandbox portal, Introduction and Technical Specifications pages; NHCX Usecases (NHA); NHCX Documentation v1.5.0",sidebar_position:2},o="What NHCX is",h={},c=[{value:"In short",id:"in-short",level:2},{value:"What it is",id:"what-it-is",level:2},{value:"What NHCX aims to achieve",id:"what-nhcx-aims-to-achieve",level:2},{value:"NHCX operating framework",id:"nhcx-operating-framework",level:2},{value:"What NHCX is made of",id:"what-nhcx-is-made-of",level:2},{value:"Who is on the network",id:"who-is-on-the-network",level:2},{value:"What changes in practice",id:"what-changes-in-practice",level:2}];function l(e){let n={h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"what-nhcx-is",children:"What NHCX is"})}),"\n",(0,a.jsx)(n.h2,{id:"in-short",children:"In short"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsx)(n.li,{children:"NHCX is one road between hospitals and insurers, replacing a separate integration per insurer."}),"\n",(0,a.jsx)(n.li,{children:"NHA states five objectives: wider cover, faster money, room to innovate, one process, a better patient experience."}),"\n",(0,a.jsx)(n.li,{children:"It is three rulebooks and a referee: the protocol, the data specifications, the operational guidelines, and NHA."}),"\n",(0,a.jsx)(n.li,{children:"Each role has a fixed list of what it may send and receive."}),"\n",(0,a.jsx)(n.li,{children:"Records cross as data rather than pictures, which is what makes automatic decisions possible."}),"\n"]}),"\n",(0,a.jsx)(n.h2,{id:"what-it-is",children:"What it is"}),"\n",(0,a.jsx)(n.p,{children:"The National Health Claims Exchange is a single road between hospitals and insurers. A hospital asks whether a patient is covered, asks permission to treat, sends the bill, and gets paid. Today each of those steps runs differently for every insurer. On the exchange they run the same way for all of them."}),"\n",(0,a.jsx)(n.p,{children:"It carries the whole journey: checking cover before admission, getting treatment approved, submitting the claim at discharge, being paid, and arguing when the answer is wrong. Every step is a message out and an answer back later, so nothing is left hanging and there is a record of both halves."}),"\n",(0,a.jsx)(n.p,{children:"Hospitals, insurers, patients, regulators and observers all connect to it the same way."}),"\n",(0,a.jsx)(n.p,{children:"NHCX is developed under the Ayushman Bharat Digital Mission (ABDM) by the National Health Authority (NHA), in consultation with the Insurance Regulatory and Development Authority of India (IRDAI). The idea is to introduce a platform of exchange to Providers and Payers so that both can transfer digitised health records and other pertinent information directly, in a machine readable format, to their counterpart."}),"\n",(0,a.jsx)(n.h2,{id:"what-nhcx-aims-to-achieve",children:"What NHCX aims to achieve"}),"\n",(0,a.jsx)(n.p,{children:"NHA states five objectives for the exchange."}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Wider cover."})," Bring new kinds of claim onto the network, including outpatient (OPD) visits and pharmacy bills, so insurance is not only about hospital stays."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Faster money."})," Shorten the time between treatment and payment, and make cashless treatment workable even in small hospitals."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Room to innovate."})," Give insurers the structured data they need to automate decisions and to spot fraud."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"One way of doing things."})," A single, rule-based process that both sides trust, instead of every insurer running its own."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"A better patient experience."})," Fewer forms, fewer delays, fewer surprises at discharge."]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Underneath all five sits one requirement. A hospital's software and an insurer's software are built by different people on different technology, and a message has to mean exactly the same thing at both ends. That is why everything on the exchange is written in one agreed format, with agreed words for diagnoses, procedures and test results. The third chapter explains what that format is and why it matters."}),"\n",(0,a.jsx)(n.h2,{id:"nhcx-operating-framework",children:"NHCX operating framework"}),"\n",(0,a.jsx)(n.p,{children:"A stock exchange works because a buyer and a seller each connect to the exchange rather than to each other. NHCX works the same way. A hospital connects once, an insurer connects once, and from then on either can reach the other without having built anything specific to them."}),"\n",(0,a.jsx)(n.h2,{id:"what-nhcx-is-made-of",children:"What NHCX is made of"}),"\n",(0,a.jsx)(n.p,{children:"It helps to think of NHCX as three rulebooks and one referee."}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"The protocol"})," says how a message travels: how it is addressed, sealed, acknowledged and answered. It is deliberately like email: a message goes to the exchange, the exchange passes it on, and the reply comes back the same way."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"The data specifications"})," say what goes inside a message. Claims, policies, payments and the rest are written as FHIR records, using profiles published by NRCeS, so that both sides read the same thing."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"The operational guidelines"})," say who may join, how they are checked, what they may do, and how they can be removed."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"NHA is the referee."})," It publishes the rules, runs the exchange, and works with NRCeS and IRDAI to change them."]}),"\n"]}),"\n",(0,a.jsxs)(n.p,{children:["Five principles run through all of it. The rules are ",(0,a.jsx)(n.strong,{children:"open"}),", published under a permissive licence so anyone can build against them. They are ",(0,a.jsx)(n.strong,{children:"evolvable"}),", so a scheme can add what it needs without breaking everyone else. They are ",(0,a.jsx)(n.strong,{children:"minimal"}),", so they are easy to understand and do not hold back innovation. They protect ",(0,a.jsx)(n.strong,{children:"privacy and security"}),", with sealed contents and tamper-proof records. And they are ",(0,a.jsx)(n.strong,{children:"unbundled"}),", so a participant can adopt one part without adopting all of it."]}),"\n",(0,a.jsx)(n.h2,{id:"who-is-on-the-network",children:"Who is on the network"}),"\n",(0,a.jsx)(n.p,{children:"Most of this documentation talks about two parties, the hospital and the insurer. The network recognises more."}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Providers."})," Hospitals and clinics, identified by their Health Facility Registry entry."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Payers."})," Insurance companies, and the government agencies that pay for schemes."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"TPAs."})," Third-party administrators who process claims on an insurer's behalf. On the network a TPA behaves like a payer."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Regulators."})," IRDAI and bodies like it, who can search claims across every payer."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Scheme sponsors."})," The owner of a programme, for example NHA for Ayushman Bharat, with payer-level access."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Researchers and insurance marketplaces."})," Given aggregated or consented data only."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Patient apps."})," Personal health record apps that receive notifications on a beneficiary's behalf."]}),"\n",(0,a.jsxs)(n.li,{children:[(0,a.jsx)(n.strong,{children:"Other exchanges."})," NHCX is designed so that more than one instance can exist and relay to each other."]}),"\n"]}),"\n",(0,a.jsx)(n.mermaid,{value:"flowchart LR\n  classDef provider fill:#DCEFE3,stroke:#2E7D4F,color:#1B2431\n  classDef payer fill:#DCE8F5,stroke:#2B5C9E,color:#1B2431\n  classDef exchange fill:#E3F0F0,stroke:#0F6E70,color:#1B2431\n  classDef other fill:#EEF1F4,stroke:#7A8797,color:#1B2431\n  H1[Hospital] --- X((NHCX))\n  H2[Clinic] --- X\n  A[Patient app] --- X\n  X --- P1[Insurer]\n  X --- P2[Government scheme]\n  X --- T[TPA]\n  X --- R[Regulator]\n  X --- N[Another exchange]\n  class H1,H2 provider\n  class P1,P2,T payer\n  class X,N exchange\n  class A,R other"}),"\n",(0,a.jsx)(n.p,{children:"Each role comes with a fixed list of what it may send and receive. A hospital can ask about eligibility and submit claims; it cannot search another hospital's claims. A regulator can search; it cannot submit."}),"\n",(0,a.jsx)(n.h2,{id:"what-changes-in-practice",children:"What changes in practice"}),"\n",(0,a.jsx)(n.p,{children:"Four things are different once a hospital is on the exchange, and the rest of this documentation is about making them work."}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Records go across as records."})," A hospital's software already holds the diagnosis, the test results and the treatment as data. Today most of it is printed or turned into a picture before it is sent, and the insurer's software cannot read a picture. On the exchange it goes across as data and stays readable."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"That makes automatic decisions possible."})," An insurer can only decide a claim by machine if it can read the values. A blood test sent as ten separate results can be checked automatically; the same test sent as a scan cannot."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"One place to type things."})," The hospital's own system becomes the single place the information is entered, rather than being re-keyed into an insurer's portal afterwards. Most rejections on technical grounds come from that second typing."]}),"\n",(0,a.jsxs)(n.p,{children:[(0,a.jsx)(n.strong,{children:"Any hospital can reach any insurer."})," A small hospital that could never afford to integrate with thirty insurers separately can integrate once."]}),"\n",(0,a.jsx)(n.p,{children:"The next chapter follows a claim from admission to payment, in the ordinary language of the people who do it, before any of this becomes technical."})]})}function d(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}}}]);